const raw = $input.first().json.content[0].text;
const cleaned = raw.replace(/```json|```/g, '').trim();
const parsed = JSON.parse(cleaned);

const original = $('Merge').first().json;

var dedupKey;
if (parsed.extracted.order_number) {
  dedupKey = original.sender_email + '_' + parsed.extracted.order_number;
} else {
  dedupKey = original.sender_email + '_' + parsed.type;
}

const result = Object.assign({}, parsed, {
  sender_name: original.sender_name,
  sender_email: original.sender_email,
  source: original.source,
  received_at: new Date().toISOString(),
  dedup_key: dedupKey
});

return [{ json: result }];

let original;

try {
  original = $('Gmail Trigger').item;
} catch (e) {
  original = null;
}

if (!original) {
  // This request didn't come from email — no attachment to hand off
  throw new Error('Invoice routing expects an email with an attachment. This request came from the website form, which does not support attachments yet.');
}

return [{
  json: original.json,
  binary: original.binary
}];

const callback = $input.first().json.callback_query;
const [action, dedupKey] = callback.data.split('|');

return [{
  json: {
    action: action,
    dedup_key: dedupKey,
    telegram_callback_id: callback.id,
    telegram_chat_id: callback.message.chat.id,
    telegram_message_id: callback.message.message_id
  }
}];
